async function api(path,data,signal){
 const r=await fetch(path,{method:data?'POST':'GET',credentials:'same-origin',signal,headers:{...(data?{'Content-Type':'application/json'}:{}),...(accessToken?{Authorization:'Bearer '+accessToken}:{})},body:data?JSON.stringify(data):undefined});
 let result;try{result=await r.json()}catch{throw new Error('连接中断，当前状态待确认；请重连查询，不要重复启动。')}
 if(!r.ok){const error=new Error(result.error||'操作未完成');error.node=result.node;error.responseStatus=r.status;throw error}return result;
}
