function retainCanvasMeasurements(previous,nodes,changes=[]){
 const live=new Map(nodes.map(n=>[n.id,n.data.node.kind]));
 const removed=new Set(changes.filter(c=>c.type==='remove').map(c=>c.id));
 const next=new Map([...previous].filter(([id,value])=>!removed.has(id)&&live.has(id)&&live.get(id)===value.kind));
 for(const c of changes){
  if(c.type!=='dimensions'||removed.has(c.id)||!live.has(c.id))continue;
  const {width,height}=c.dimensions||{};
  if(!Number.isFinite(width)||!Number.isFinite(height)||width<=0||height<=0)continue;
  const before=next.get(c.id);
  if(before?.measured.width!==width||before?.measured.height!==height)
   next.set(c.id,{kind:live.get(c.id),measured:{width,height}});
 }
 return next.size===previous.size&&[...next].every(([id,value])=>previous.get(id)===value)?previous:next;
}
function CanvasHandleMeasurements(){
 const updateNodeInternals=useUpdateNodeInternals();
 // A pending controlled update can clear handle bounds between DOM measurement
 // and the dimensions callback's render. Same-size nodes need no new RO event.
 const missing=useStore(s=>JSON.stringify([...s.nodeLookup.values()].filter(n=>
  !n.hidden&&n.measured.width>0&&n.measured.height>0&&!n.internals.handleBounds
 ).map(n=>n.id)));
 useEffect(()=>{const ids=JSON.parse(missing);if(ids.length)updateNodeInternals(ids)},[missing,updateNodeInternals]);
 return null;
}
function CanvasInitialRunView({ready}){
 const initialized=useNodesInitialized(),{fitView}=useReactFlow(),framed=useRef(false);
 // A run may be selected before its exact frozen snapshot arrives. Frame its
 // measured graph once, without moving the camera on later polls or selection.
 useEffect(()=>{if(!ready||!initialized||framed.current)return;framed.current=true;fitView({padding:.2,maxZoom:1,minZoom:.55})},[ready,initialized,fitView]);
 return null;
}
function MeasuredCanvas({nodes,onNodesChange,children,...props}){
 // Measurements belong to this mounted canvas, never the canonical graph.
 const [measurements,setMeasurements]=useState(()=>new Map());
 useEffect(()=>{setMeasurements(old=>retainCanvasMeasurements(old,nodes))},[nodes]);
 const measuredNodes=nodes.map(n=>{const size=measurements.get(n.id);return size?.kind===n.data.node.kind?{...n,measured:size.measured}:n});
 return <ReactFlow {...props} nodes={measuredNodes} onNodesChange={changes=>{
  setMeasurements(old=>retainCanvasMeasurements(old,nodes,changes));
  onNodesChange(changes);
 }}><CanvasHandleMeasurements/>{children}</ReactFlow>;
}

